/* @lc app=leetcode id=1851 lang=kotlin */ class Solution { fun minInterval(intervals: Array<IntArray>, queries: IntArray): IntArray = intervals.sortedBy { it[0] }.let { iv -> java.util.PriorityQueue<IntArray>(compareBy<IntArray> { it[0] }).let { pq -> IntArray(queries.size).also { ans -> queries.indices.sortedBy { queries[it] }.fold(0) { p, qi -> (p + generateSequence(p) { it + 1 }.takeWhile { it < iv.size && iv[it][0] <= queries[qi] }.onEach { pq.add(intArrayOf(iv[it][1] - iv[it][0] + 1, iv[it][1])) }.count()).also { generateSequence { pq.peek()?.takeIf { it[1] < queries[qi] } }.forEach { _ -> pq.poll() } }.also { ans[qi] = pq.peek()?.get(0) ?: -1 } } } } } }